import React, { useEffect } from 'react';

const Toast = ({ toast, onRemove }) => {
  useEffect(() => {
    const timeout = setTimeout(() => {
      onRemove(toast.id);
    }, 3000);
    return () => clearTimeout(timeout);
  }, [toast.id, onRemove]);

  return (
    <div
      className={`flex items-start min-w-[250px] max-w-[350px] px-4 py-3 rounded shadow-lg bg-white border-l-4 ${
        toast.type === 'success'
          ? 'border-green-500'
          : toast.type === 'error'
          ? 'border-red-500'
          : 'border-yellow-400'
      }`}
    >
      <div className={`flex items-center justify-center w-6 h-6 rounded-full mr-3 ${
        toast.type === 'success'
          ? 'bg-green-500 text-white'
          : toast.type === 'error'
          ? 'bg-red-500 text-white'
          : 'bg-yellow-400 text-white'
      }`}>
        <i className={`bi ${toast.type === 'success' ? 'bi-check-lg' : toast.type === 'error' ? 'bi-x-lg' : 'bi-exclamation-lg'}`}></i>
      </div>
      <div className="flex-1">
        <div className="font-bold">{toast.title}</div>
        <div className="text-sm">{toast.message}</div>
      </div>
      <button
        className="ml-4 text-gray-500 hover:text-gray-800 text-xl font-bold focus:outline-none"
        onClick={() => onRemove(toast.id)}
      >
        ×
      </button>
    </div>
  );
};

const ToastContainer = ({ toasts, setToasts }) => {
  const removeToast = (id) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  return (
    <div className="fixed top-4 right-4 z-50 flex flex-col gap-2">
      {toasts.map((toast) => (
        <Toast key={toast.id} toast={toast} onRemove={removeToast} />
      ))}
    </div>
  );
};

export default ToastContainer;
